// generar_302_visita_a_historial_y_fechas_antiguas.js
// CHIQUI Entre Señales — Visita en Historial médico + rango de años ampliado
//
// Dos ajustes:
//
// 1. La sección "Visitas veterinarias" se MUEVE de "Signos vitales" a
//    "Historial médico" (Área 3), que es donde corresponde: una visita
//    al veterinario es un evento médico, no un signo vital. Queda junto
//    a Enfermedades, Observaciones y Exámenes.
//
// 2. El selector de fecha (FechaSelector) ahora llega mucho más atrás:
//    de 10 años pasados a 30. Antes solo permitía hasta ~2016, lo que
//    dejaba fuera a mascotas longevas (perros y gatos de 20-25 años, y
//    aves/tortugas que viven aún más). Ahora el rango va de +10 años en
//    el futuro (para vacunas/tratamientos) hasta 30 años atrás. Como el
//    FechaSelector se usa en TODA la app, esto aplica a nacimiento,
//    vacunas, visitas y cualquier fecha.
//
// No hay SQL.
//
// Uso:
//   node generar_302_visita_a_historial_y_fechas_antiguas.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: "app/prevencion/page.tsx",
    base64: ""
  },
  {
    ruta: "components/FechaSelector.tsx",
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 2 archivos escritos. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
